// src/security/catalog/index.ts
var RULES = [...COMMON, ...ANDROID, ...IOS, ...WEB, ...BACKEND, ...CROSS_MOBILE, ...DESKTOP];
function rulesFor(platforms) {
  return RULES.filter((r) => r.platform === "common" || platforms.has(r.platform));
}

